={{ JSON.stringify({
  query: `query ($base: String!, $baseRef: String!, $branchRef: String!) {
    repository(owner: "kentayamada-dev", name: "n8n") {
      id
      nameWithOwner
      base: ref(qualifiedName: $baseRef) {
        target { ...workflows }
      }
      branch: ref(qualifiedName: $branchRef) {
        id
        associatedPullRequests(states: OPEN, baseRefName: $base, first: 1) { totalCount }
        target { ...workflows }
      }
    }
  }
  fragment workflows on Commit {
    oid
    file(path: "workflows") {
      object {
        ... on Tree {
          entries { name object { ... on Blob { text isTruncated } } }
        }
      }
    }
  }`,
  variables: {
    base: $('設定').first().json.base,
    baseRef: 'refs/heads/' + $('設定').first().json.base,
    branchRef: 'refs/heads/' + $('設定').first().json.branch,
  },
}) }}

parameters.jsCode:
// n8n のワークフローを GitHub のファイルと比べて、GitHub に反映する操作を 1 回の GraphQL の mutation にまとめる
// 変更が無ければ何も返さずに止める（ブランチも PR も触らない）
const { branch: branchName, base: baseName } = $('設定').first().json;

// GitHub の状態（「GitHubの状態を取得」の結果）
// GraphQL は失敗しても HTTP 200 で errors を返すので、ここで確かめる
const res = $('GitHubの状態を取得').first().json;
const repository = res.data?.repository;
if (res.errors?.length || !repository?.base) {
  const reason = (res.errors ?? []).map((e) => e.message).join(' / ') || JSON.stringify(res).slice(0, 300);
  throw new Error(`GitHub の状態を取得できませんでした: ${reason}`);
}

// PR が開いていれば、そのブランチと比べて続きにコミットする
// 開いていなければ（マージした・閉じた・まだ無い）main と比べ、ブランチを main に戻して（無ければ作って）からコミットし、PR を作る
const hasPR = repository.branch?.associatedPullRequests.totalCount > 0;
const head = hasPR ? repository.branch.target : repository.base.target;

// 比べる相手のファイル（ファイル名 → 中身）
const githubFiles = new Map();
// workflows/ がまだ無いときは file が null になる
for (const { name, object } of head.file?.object?.entries ?? []) {
  if (!name.endsWith('.json')) continue;
  // 大きすぎるファイルは中身が途中で切られる。そのまま比べると毎回「変更あり」になるので、エラーにして知らせる
  if (object?.isTruncated) {
    throw new Error(`workflows/${name} が大きく、GitHub から中身を全部は取得できませんでした`);
  }
  githubFiles.set(name, object?.text);
}

const n8nWorkflows = $input.all().map((i) => i.json);

// 安全装置: n8nから取れた一覧に、このワークフロー自身が入っていなければ何も削除せずに止める。
// 一覧が空、またはAPIキーの持ち主・プロジェクトが違って一部しか見えていないと、GitHubのファイルを全部消してしまうため。
// 正しく動いていればこの状態にはならないので、黙って飛ばさずにエラーにして「エラー通知」でSlackに知らせる
// （ここで止まるので、その日のバックアップも行われない）
if (!n8nWorkflows.some((w) => w.id === $workflow.id)) {
  throw new Error(
    `n8nから取得したワークフロー一覧（${n8nWorkflows.length}件）に、このワークフロー自身が含まれていません。`
    + "認証情報「n8n account」のAPIキーの持ち主とプロジェクトを確認してください。GitHubのファイルは削除していません。",
  );
}

const changes = []; // コミットメッセージに並べる「add / update / delete: 名前」
const additions = [];
const deletions = [];
const n8nFiles = new Set();

for (const wf of n8nWorkflows) {
  // 公開リポジトリにコミットするので、ワークフローの中身ではない項目を外してから比べる
  // - staticData: 実行のたびに変わる状態（前回の実行日・取得したレートなど）。入れたままだと毎日「変更あり」になる
  // - pinData: 画面でテスト用に固定した実行データ。Binance の残高や支出などの実データがそのまま入る
  // - activeVersion / shared: 公開中の版の写しと、前の n8n のプロジェクト情報。取り込むときにも消している（import-workflows.sh）
  // - versionId / activeVersionId / updatedAt / triggerCount: 保存・公開・有効化のたびに n8n が書き換える管理用の値。
  //   入れたままだと、中身が同じでも「公開しただけ」「変えずに保存しただけ」でコミットされる。
  //   取り込むとき n8n は versionId を作り直し activeVersionId を空にするので、無くても復元に困らない
  // active（有効/無効）は残す。切り替えは意味のある変化で、取り込み時に --activeState=fromJson で使える
  const { staticData, pinData, activeVersion, shared, versionId, activeVersionId, updatedAt, triggerCount, ...workflow } = wf;
  const file = `${workflow.name}.json`;
  n8nFiles.add(file);

  // ファイルの形（2 文字下げ・最後に改行なし）は変えない。変えると全部のファイルが「変更あり」になる
  const text = JSON.stringify(workflow, null, 2);
  if (githubFiles.get(file) === text) continue;

  changes.push({ action: githubFiles.has(file) ? 'update' : 'add', name: workflow.name });
  // createCommitOnBranch は中身を base64 で受け取る
  additions.push({ path: `workflows/${file}`, contents: Buffer.from(text).toString('base64') });
}

// GitHub にあって、n8n に無くなったワークフローのファイルを消す
for (const file of githubFiles.keys()) {
  if (n8nFiles.has(file)) continue;
  changes.push({ action: 'delete', name: file.replace(/\.json$/, '') });
  deletions.push({ path: `workflows/${file}` });
}

if (changes.length === 0) {
  return [];
}

// 1 件なら「update: 支出記録」。複数なら見出しは「update: 支出記録 ほか 2 件」にして、本文に 1 件ずつ並べる
const lines = changes.map((c) => `${c.action}: ${c.name}`);
const prefix = new Set(changes.map((c) => c.action)).size === 1 ? changes[0].action : 'update';
const message = changes.length === 1
  ? { headline: lines[0] }
  : { headline: `${prefix}: ${changes[0].name} ほか ${changes.length - 1} 件`, body: lines.join('\n') };

// GitHub に反映する操作。1 回の mutation の中で上から順に動き、前の操作の結果は次の操作に反映される
// 途中が失敗しても後ろは動く（例: コミットが失敗すると PR 作成も「No commits between」で失敗する）ので、「反映できたか確認」で errors を見て止める
// ブランチを戻すのは PR が無いときだけなので、どこで失敗しても、次の実行で戻すところからやり直せる
const steps = [];
if (!hasPR && !repository.branch) {
  steps.push({
    op: 'createRef',
    input: { repositoryId: repository.id, name: `refs/heads/${branchName}`, oid: head.oid },
    returns: 'ref { name }',
  });
} else if (!hasPR && repository.branch.target.oid !== head.oid) {
  // PR を閉じたときなどに残っているコミットは捨てる
  steps.push({
    op: 'updateRef',
    input: { refId: repository.branch.id, oid: head.oid, force: true },
    returns: 'ref { name }',
  });
}
steps.push({
  op: 'createCommitOnBranch',
  input: {
    branch: { repositoryNameWithOwner: repository.nameWithOwner, branchName },
    // 比べたときの先頭。それまでにブランチが進んでいたら、GitHub がコミットを拒否する
    expectedHeadOid: head.oid,
    message,
    fileChanges: { additions, deletions },
  },
  returns: 'commit { url }',
});
if (!hasPR) {
  steps.push({
    op: 'createPullRequest',
    input: {
      repositoryId: repository.id,
      baseRefName: baseName,
      headRefName: branchName,
      title: `update: n8n のワークフロー（${$now.toFormat('yyyy-MM-dd')}〜）`,
      body: [
        '「ワークフローバックアップ」が、n8n のワークフローの変更をまとめた PR です。',
        '',
        '- マージするまでは、変更があるたびにこのブランチへコミットを足していきます',
        '- マージすると main に入ります。次に変更があったとき、新しい PR を作ります',
        '- マージせずに閉じても、n8n の中身が main と違うままなら、次の実行でブランチを main に戻して PR を作り直します',
      ].join('\n'),
    },
    returns: 'pullRequest { url }',
  });
}

// 例: mutation ($createCommitOnBranch: CreateCommitOnBranchInput!) {
//       createCommitOnBranch(input: $createCommitOnBranch) { commit { url } }
//     }
const query = [
  `mutation (${steps.map(({ op }) => `$${op}: ${op[0].toUpperCase()}${op.slice(1)}Input!`).join(', ')}) {`,
  ...steps.map(({ op, returns }) => `  ${op}(input: $${op}) { ${returns} }`),
  '}',
].join('\n');
const variables = Object.fromEntries(steps.map(({ op, input }) => [op, input]));

return [{ json: { query, variables } }];

// GraphQL は失敗しても HTTP 200 で errors を返すので、HTTP Request ノードはエラーにならない
// mutation の中の操作は途中が失敗しても後ろが動くので、1 つでも失敗していたらエラーにして「エラー通知」で Slack に知らせる
// expectedHeadOid が合わない（比べてからコミットするまでにブランチが進んだ）ときもここで止まる。次の実行でやり直す
const res = $input.first().json;

if (res.errors?.length || !res.data) {
  const reason = (res.errors ?? []).map((e) => `${e.path?.join('.') ?? '-'}: ${e.message}`).join(' / ') || JSON.stringify(res).slice(0, 300);
  throw new Error(`GitHub に反映できませんでした: ${reason}`);
}

return [{ json: res.data }];
